/*global tinymce:true */

tinymce.PluginManager.add('imagegrid', function (editor, url) {

    var colRegex = /(\d)c/i;
    var rowRegex = /(\d)r/i;
    var lRegex = /(\d)(r|c)/gi;

    var layouts = [
        { type: "1r", text: "1 row" },
        { type: "1r2c", text: "1 row, 2 cols" },
        { type: "2c", text: "2 cols" },
        { type: "2c1r", text: "2 cols, 1 row" },
        { type: "3c", text: "3 cols" },
        { type: "3c1r", text: "3 cols, 1 row" },
        { type: "4c", text: "4 cols" }
    ];

    var img = '<img loading="lazy" src="/_content/Origami.UI/lib/tinymce-5.10.7/plugins/imagegrid/select-image.png" style="width:100%;height:100%;" alt="select image" />';

    //generates the image grid inside the editor's content
    function imagegrid(type) {
        return function () {

            var layout = type.match(lRegex);
            var newHtml = "";

            for (var i = 0; i < layout.length; i++) {
                var item = layout[i];

                //rows
                if (item.match(/r$/i)) {
                    var nrows = item.match(rowRegex);
                    for (var x = 0; x < nrows[1]; x++) { newHtml += '<div class="w-100">' + img + '</div>'; }
                }

                //cols
                if (item.match(/c$/i)) {
                    var ncols = item.match(colRegex);
                    newHtml += '<div class="row">';
                    for (var x = 0; x < ncols[1]; x++) {
                        newHtml += '<div class="col-' + 12 / ncols[1] + '">' + img + '</div>';
                    }
                    newHtml += '</div><p></p>';
                }
            }

            //html inside a paragraph
            newHtml = "<p>" + newHtml + "</p>";

            // get hold on TinyMce editor and inject link
            top.tinymce.activeEditor.insertContent(newHtml);
        };
    };

    // Inside plugin
    editor.ui.registry.addNestedMenuItem('imagegrid', {
        text: "Image grid",
        icon: "image",
        getSubmenuItems: function () {
            //new array
            var items = [];

            for (var i = 0; i < layouts.length; i++) {
                var layout = layouts[i];
                var item = {
                    type: "menuitem", text: layout.text, context: "imagegrid", layout: layout.type, onAction: imagegrid(layout.type),
                };
                //adding the button to the html layout
                items.push(item);
            }

            return items;
        },
    });

});
